1	import { toSignal } from '@angular/core/rxjs-interop';
2	import { DestroyRef, DOCUMENT, Injectable, computed, effect, inject, signal } from '@angular/core';
3	import { NavigationEnd, Router } from '@angular/router';
4	import { filter, map } from 'rxjs';
5	
6	export interface NavItem {
7	  readonly path: string;
8	  readonly label: string;
9	  readonly icon: string;
10	}
11	
12	export interface Crumb {
13	  readonly label: string;
14	  readonly path?: string;
15	}
16	
17	const THEME_KEY = 'hero-ops-theme';
18	const DARK_QUERY = '(prefers-color-scheme: dark)';
19	
20	// The hero detail screen is reached from the roster, so it is not a rail destination.
21	const NAV_ITEMS: readonly NavItem[] = [
22	  { path: '/dashboard', label: 'Dashboard', icon: 'lucideLayoutDashboard' },
23	  { path: '/roster', label: 'Roster', icon: 'lucideUsers' },
24	  { path: '/missions', label: 'Missions', icon: 'lucideTarget' },
25	  { path: '/threats', label: 'Threats', icon: 'lucideShieldAlert' },
26	  { path: '/recruit', label: 'Recruit', icon: 'lucideUserPlus' },
27	  { path: '/settings', label: 'Settings', icon: 'lucideSettings' },
28	];
29	
30	const SECTION_LABELS: Partial<Record<string, string>> = {
31	  dashboard: 'Dashboard',
32	  roster: 'Roster',
33	  missions: 'Missions',
34	  recruit: 'Recruit',
35	  threats: 'Threats',
36	  settings: 'Settings',
37	};
38	
39	function readStoredTheme(win: Window | null): 'light' | 'dark' | null {
40	  try {
41	    const value = win?.localStorage.getItem(THEME_KEY);
42	    return value === 'light' || value === 'dark' ? value : null;
43	  } catch {
44	    return null;
45	  }
46	}
47	
48	@Injectable()
49	export class AppViewModel {
50	  private readonly document = inject(DOCUMENT);
51	  private readonly router = inject(Router);
52	  private readonly win = this.document.defaultView;
53	  private readonly systemDark = this.win?.matchMedia?.(DARK_QUERY) ?? null;
54	  private readonly stored = readStoredTheme(this.win);
55	
56	  readonly navItems = NAV_ITEMS;
57	  readonly query = signal('');
58	  private readonly isDark = signal(this.stored ? this.stored === 'dark' : (this.systemDark?.matches ?? false));
59	  readonly themeIcon = computed(() => (this.isDark() ? 'lucideSun' : 'lucideMoon'));
60	  readonly themeLabel = computed(() =>
61	    this.isDark() ? 'Switch to light theme' : 'Switch to dark theme',
62	  );
63	
64	  private readonly url = toSignal(
65	    this.router.events.pipe(
66	      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
