import { toSignal } from '@angular/core/rxjs-interop';
import { DestroyRef, DOCUMENT, Injectable, computed, effect, inject, signal } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { filter, map } from 'rxjs';

export interface NavItem {
  readonly path: string;
  readonly label: string;
  readonly icon: string;
}

export interface Crumb {
  readonly label: string;
  readonly path?: string;
}

const THEME_KEY = 'hero-ops-theme';
const DARK_QUERY = '(prefers-color-scheme: dark)';

// The hero detail screen is reached from the roster, so it is not a rail destination.
const NAV_ITEMS: readonly NavItem[] = [
  { path: '/dashboard', label: 'Dashboard', icon: 'lucideLayoutDashboard' },
  { path: '/roster', label: 'Roster', icon: 'lucideUsers' },
  { path: '/missions', label: 'Missions', icon: 'lucideTarget' },
  { path: '/threats', label: 'Threats', icon: 'lucideShieldAlert' },
  { path: '/recruit', label: 'Recruit', icon: 'lucideUserPlus' },
  { path: '/settings', label: 'Settings', icon: 'lucideSettings' },
];

const SECTION_LABELS: Partial<Record<string, string>> = {
  dashboard: 'Dashboard',
  roster: 'Roster',
  missions: 'Missions',
  recruit: 'Recruit',
  threats: 'Threats',
  settings: 'Settings',
};

function readStoredTheme(win: Window | null): 'light' | 'dark' | null {
  try {
    const value = win?.localStorage.getItem(THEME_KEY);
    return value === 'light' || value === 'dark' ? value : null;
  } catch {
    return null;
  }
}

@Injectable()
export class AppViewModel {
  private readonly document = inject(DOCUMENT);
  private readonly router = inject(Router);
  private readonly win = this.document.defaultView;
  private readonly systemDark = this.win?.matchMedia?.(DARK_QUERY) ?? null;
  private readonly stored = readStoredTheme(this.win);

  readonly navItems = NAV_ITEMS;
  readonly query = signal('');
  private readonly isDark = signal(this.stored ? this.stored === 'dark' : (this.systemDark?.matches ?? false));
  readonly themeIcon = computed(() => (this.isDark() ? 'lucideSun' : 'lucideMoon'));
  readonly themeLabel = computed(() =>
    this.isDark() ? 'Switch to light theme' : 'Switch to dark theme',
  );

  private readonly url = toSignal(
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
      map((event) => event.urlAfterRedirects),
    ),
    { initialValue: '/' },
  );

  readonly crumbs = computed<readonly Crumb[]>(() => {
    const [section = '', id] = this.url().split(/[?#]/)[0].split('/').filter(Boolean);
    if (section === 'detail' && id) {
      return [{ label: 'Roster', path: '/roster' }, { label: `Hero ${id}` }];
    }
    return [{ label: SECTION_LABELS[section] ?? 'Dashboard' }];
  });

  constructor() {
    effect(() => this.document.documentElement.classList.toggle('dark', this.isDark()));

    // With no stored choice, follow the operating system's colour scheme as it changes.
    const onSystemChange = (event: MediaQueryListEvent) => {
      if (readStoredTheme(this.win) === null) this.isDark.set(event.matches);
    };
    this.systemDark?.addEventListener('change', onSystemChange);
    inject(DestroyRef).onDestroy(() =>
      this.systemDark?.removeEventListener('change', onSystemChange),
    );
  }

  toggleTheme(): void {
    const next = !this.isDark();
    this.isDark.set(next);
    try {
      this.win?.localStorage.setItem(THEME_KEY, next ? 'dark' : 'light');
    } catch {
      // Storage is unavailable (private mode, blocked cookies): the choice still applies this visit.
    }
  }

  setQuery(value: string): void {
    this.query.set(value);
  }
}

