import { z } from 'zod';
import { POWER_CLASSES } from '../domain/hero.model';

// The edit form's single source of truth: shape, rules, and field labels.
// Labels and control kinds ride on `.meta()`; read them with `formMeta()`.
export const heroDetailSchema = z.object({
  name: z.string().trim().min(1).meta({ label: 'Name', control: 'text', placeholder: 'Public-facing hero name' }),
  alias: z.string().trim().min(1).meta({ label: 'Alias', control: 'text', placeholder: 'Civilian identity' }),
  powerClass: z.enum(POWER_CLASSES).meta({
    label: 'Power class',
    control: 'select',
    options: POWER_CLASSES.map((value) => ({ value, label: value })),
  }),
  powerIndex: z.number().int().min(0).max(100).meta({
    label: 'Power index',
    control: 'number',
    help: 'Between 0 and 100.',
  }),
});

export type HeroModel = z.infer<typeof heroDetailSchema>;
